import {useEffect, useState} from 'react';
import '../styles/Item.css';

function Item({item, addToCart}) {
    const [isDetailOpen, setIsDetailOpen] = useState(false);

    useEffect(() => {
        if (!isDetailOpen) return;

        const onKeyDown = (event) => {
            if (event.key === 'Escape') {
                setIsDetailOpen(false);
            }
        };

        window.addEventListener('keydown', onKeyDown);
        return () => window.removeEventListener('keydown', onKeyDown);
    }, [isDetailOpen]);

    return (
        <li className='catalog__card' key={item.id ?? item.name}>
            <div className="item__catalog">
                <button
                    type="button"
                    className="item__catalog__media item__catalog__media--button"
                    onClick={() => setIsDetailOpen(true)}
                >
                    {item.cover ? (
                        <img src={item.cover} alt={item.name}/>
                    ) : (
                        <div className="item__catalog__media-placeholder"/>
                    )}
                </button>
                {item.onSale && <span className="item__catalog__badge">Promo</span>}
            </div>
            <div className="item__catalog__body">
                <div className="item__catalog__name">{item.name}</div>
                <div className="item__catalog__info">
                    {item.size && <span>Taille {item.size}</span>}
                    <span>Comfort {item.comfort}</span>
                </div>
                <div className="item__catalog__footer">
                    <div className="item__catalog__price">{item.price} €</div>
                    <button className="btn btn--ghost" onClick={() => addToCart(item)}>
                        Ajouter
                    </button>
                </div>
            </div>

            {isDetailOpen && (
                <div className="item-modal__overlay" onClick={() => setIsDetailOpen(false)}>
                    <div className="item-modal__content" onClick={(event) => event.stopPropagation()}>
                        <button
                            type="button"
                            className="item-modal__close"
                            onClick={() => setIsDetailOpen(false)}
                        >
                            Fermer
                        </button>

                        <div className="item-modal__media">
                            {item.cover ? (
                                <img src={item.cover} alt={item.name}/>
                            ) : (
                                <div className="item__catalog__media-placeholder"/>
                            )}
                        </div>

                        <h2 className="item-modal__title">{item.name}</h2>
                        <p className="item-modal__description">
                            {item.description || `Piece ${item.category || 'streetwear'} au style neon, confortable et prete pour la scene.`}
                        </p>
                        <p>Prix : {item.price} euros</p>
                        {item.size && <p>Taille : {item.size}</p>}
                        {item.comfort && <p>Confort : {item.comfort}</p>}

                        <div className="item-modal__actions">
                            <button
                                className="btn"
                                onClick={() => addToCart(item)}
                            >
                                Ajouter au panier
                            </button>
                            <button
                                className="btn btn--ghost"
                                onClick={() => setIsDetailOpen(false)}
                            >
                                Retour
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </li>
    );
}

export default Item;
